   131  bool ProcessTTF(ots::FontFile *header,
   132                  ots::Font *font,
   133                  ots::OTSStream *output, const uint8_t *data, size_t length,
   134                  uint32_t offset = 0) {
   135    ots::Buffer file(data + offset, length - offset);
   136
   137    if (offset > length) {
   138      return OTS_FAILURE_MSG_HDR("offset beyond end of file");
   139    }
   140
   141    // we disallow all files > 1GB in size for sanity.
   142    if (length > 1024 * 1024 * 1024) {
   143      return OTS_FAILURE_MSG_HDR("file exceeds 1GB");
   144    }
   145
   146    if (!file.ReadU32(&font->version)) {
   147      return OTS_FAILURE_MSG_HDR("error reading version tag");
   148    }
   149    if (!ots::IsValidVersionTag(font->version)) {
   150        return OTS_FAILURE_MSG_HDR("invalid version tag");
   151    }
   152
   153    if (!file.ReadU16(&font->num_tables) ||
   154        !file.ReadU16(&font->search_range) ||
   155        !file.ReadU16(&font->entry_selector) ||
   156        !file.ReadU16(&font->range_shift)) {
   157      return OTS_FAILURE_MSG_HDR("error reading table directory search header");
   158    }
   159
   160    // search_range is (Maximum power of 2 <= numTables) x 16. Thus, to avoid
   161    // overflow num_tables is, at most, 2^16 / 16 = 2^12
   162    if (font->num_tables >= 4096 || font->num_tables < 1) {
   163      return OTS_FAILURE_MSG_HDR("excessive (or zero) number of tables");
   164    }
   165
   166    unsigned max_pow2 = 0;
   167    while (1u << (max_pow2 + 1) <= font->num_tables) {
   168      max_pow2++;
   169    }
   170    const uint16_t expected_search_range = (1u << max_pow2) << 4;
   171
   172    // Don't call ots_failure() here since ~25% of fonts (250+ fonts) in
   173    // http://www.princexml.com/fonts/ have unexpected search_range value.
   174    if (font->search_range != expected_search_range) {
   175      OTS_WARNING_MSG_HDR("bad search range");
   176      font->search_range = expected_search_range;  // Fix the value.
   177    }
   178
   179    // entry_selector is Log2(maximum power of 2 <= numTables)
   180    if (font->entry_selector != max_pow2) {
   181      return OTS_FAILURE_MSG_HDR("incorrect entrySelector for table directory");
   182    }
   183
   184    // range_shift is NumTables x 16-searchRange. We know that 16*num_tables
   185    // doesn't over flow because we range checked it above. Also, we know that
   186    // it's > font->search_range by construction of search_range.
   187    const uint16_t expected_range_shift =
   188        16 * font->num_tables - font->search_range;
   189    if (font->range_shift != expected_range_shift) {
   190      OTS_WARNING_MSG_HDR("bad range shift");
   191      font->range_shift = expected_range_shift;  // the same as above.
   192    }
   193
   194    // Next up is the list of tables.
   195    std::vector<ots::TableEntry> tables;
   196
   197    for (unsigned i = 0; i < font->num_tables; ++i) {
   198      ots::TableEntry table;
   199      if (!file.ReadU32(&table.tag) ||
   200          !file.ReadU32(&table.chksum) ||
   201          !file.ReadU32(&table.offset) ||
   202          !file.ReadU32(&table.length)) {
   203        return OTS_FAILURE_MSG_HDR("error reading table directory");
   204      }
   205
   206      table.uncompressed_length = table.length;
   207      tables.push_back(table);
   208    }
   209
   210    return ProcessGeneric(header, font, font->version, output, data, length,
   211                          tables, file);
   212  }
