   301  bool ProcessWOFF(ots::FontFile *header,
   302                   ots::Font *font,
   303                   ots::OTSStream *output, const uint8_t *data, size_t length) {
   304    ots::Buffer file(data, length);
   305
   306    // we disallow all files > 1GB in size for sanity.
   307    if (length > 1024 * 1024 * 1024) {
   308      return OTS_FAILURE_MSG_HDR("file exceeds 1GB");
   309    }
   310
   311    uint32_t woff_tag;
   312    if (!file.ReadU32(&woff_tag)) {
   313      return OTS_FAILURE_MSG_HDR("error reading WOFF marker");
   314    }
   315
   316    if (woff_tag != OTS_TAG('w','O','F','F')) {
   317      return OTS_FAILURE_MSG_HDR("invalid WOFF marker");
   318    }
   319
   320    if (!file.ReadU32(&font->version)) {
   321      return OTS_FAILURE_MSG_HDR("error reading version tag");
   322    }
   323    if (!ots::IsValidVersionTag(font->version)) {
   324      return OTS_FAILURE_MSG_HDR("invalid version tag");
   325    }
   326
   327    uint32_t reported_length;
   328    if (!file.ReadU32(&reported_length) || length != reported_length) {
   329      return OTS_FAILURE_MSG_HDR("incorrect file size in WOFF header");
   330    }
